// frontend/src/components/ReportViewer.tsx
import React from "react";
import { ReportJson } from "../types/report";

interface ReportViewerProps {
  reportJson: ReportJson;
}

const ReportViewer: React.FC<ReportViewerProps> = ({ reportJson }) => (
  <div>
    <div>
      Report Generated On: {new Date(reportJson.reportGeneratedOn).toLocaleString()}
    </div>
    <table>
      <thead>
        <tr>
          <th>Name</th>
          <th>Start</th>
          <th>End</th>
          <th>Venue</th>
          <th>#Attendees</th>
        </tr>
      </thead>
      <tbody>
        {reportJson.data.map((r) => (
          <tr key={r.id}>
            <td>{r.name}</td>
            <td>{new Date(r.startTimeUtc).toLocaleString()}</td>
            <td>{new Date(r.endTimeUtc).toLocaleString()}</td>
            <td>{r.venue}</td>
            <td>{r.attendeeCount}</td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

export default ReportViewer;
